import os, csv, json
from pathlib import Path
from decimal import Decimal

DIR = Path(os.environ["CONSUMER_FLOW_DIR"])
dates = ["20191223","20191224","20191225","20191226","20191227","20191228","20191229"]

daily = {}
skipped = []
for d in dates:
    p = DIR / f"{d}_consumer.csv"
    if not p.exists():
        skipped.append(d)
        continue
    sums = {}
    total = Decimal("0")
    with open(p, newline="", encoding="utf-8") as f:
        for row in csv.DictReader(f):
            pt = (row.get("供气点") or "").strip()
            if not pt:
                continue
            v = Decimal((row.get("消耗量") or "0").strip() or "0")
            sums[pt] = sums.get(pt, Decimal("0")) + v
            total += v
    if total <= 0:
        skipped.append(d)
        continue
    shares = {k: v / total for k, v in sums.items()}
    hhi = sum((s * s for s in shares.values()))
    daily[d] = {
        "supply_points": len(sums),
        "total_consumption": float(total),
        "hhi": float(hhi),
        "shares": {k: float(s) for k, s in shares.items()},
    }

hhis = {d: v["hhi"] for d, v in daily.items()}
avg = sum(hhis.values()) / len(hhis) if hhis else None
peak_date = max(hhis, key=lambda k: hhis[k]) if hhis else None

result = {
    "participating_days": len(daily),
    "skipped_dates": skipped,
    "daily_hhi": {d: round(v["hhi"], 6) for d, v in daily.items()},
    "average_hhi": round(avg, 6) if avg is not None else None,
    "peak_hhi": round(max(hhis.values()), 6) if hhis else None,
    "peak_date": peak_date,
    "daily_detail": {
        d: {
            "supply_point_count": v["supply_points"],
            "total_consumption": round(v["total_consumption"], 3),
            "hhi": round(v["hhi"], 6),
            "supply_point_shares": {k: round(s, 6) for k, s in v["shares"].items()},
        }
        for d, v in daily.items()
    },
}
out = Path(os.environ["OUTPUT_DIR"]) / "consumer_hhi_20191223_20191229.json"
out.write_text(json.dumps(result, ensure_ascii=False, indent=2, default=str), encoding="utf-8")
print(json.dumps(result, ensure_ascii=False, indent=2, default=str))

